import torch
import torch.nn as nn
import avelang
import avelang.language as al

TILE_N = 8
BLOCK_SIZE = 256


# ---------------------------------------------------------------------------
# Kernel: reduce over dim 0  (B, D, N) -> (D, N)
# Each block handles TILE_N output elements along N.
# ---------------------------------------------------------------------------
@avelang.jit
def min_reduce_dim0_kernel(
    x_ptr: al.Pointer(al.bf16),
    out_ptr: al.Pointer(al.bf16),
    B: al.i32,
    D: al.i32,
    N: al.i32,
    TILE: al.constexpr,
    BLK: al.constexpr,
):
    T = TILE
    BS = BLK
    x_stride_0 = D * N
    x_layout = al.make_layout((B, D, N), (x_stride_0, N, 1))
    x = al.make_tensor(x_ptr, al.bf16, x_layout)

    out_layout = al.make_layout((D, N), (N, 1))
    out = al.make_tensor(out_ptr, al.bf16, out_layout)

    tid = al.thread_id(0)
    d_idx = al.block_id(0)
    n_start = al.block_id(1) * T

    INF = al.convert(3.402823e+38, al.f32)

    # Local accumulators for TILE_N output elements
    min0 = INF
    min1 = INF
    min2 = INF
    min3 = INF
    min4 = INF
    min5 = INF
    min6 = INF
    min7 = INF

    for b in al.range(tid, B, BS):
        v = al.convert(x[b, d_idx, n_start + 0], al.f32)
        if v < min0:
            min0 = v
        v = al.convert(x[b, d_idx, n_start + 1], al.f32)
        if v < min1:
            min1 = v
        v = al.convert(x[b, d_idx, n_start + 2], al.f32)
        if v < min2:
            min2 = v
        v = al.convert(x[b, d_idx, n_start + 3], al.f32)
        if v < min3:
            min3 = v
        v = al.convert(x[b, d_idx, n_start + 4], al.f32)
        if v < min4:
            min4 = v
        v = al.convert(x[b, d_idx, n_start + 5], al.f32)
        if v < min5:
            min5 = v
        v = al.convert(x[b, d_idx, n_start + 6], al.f32)
        if v < min6:
            min6 = v
        v = al.convert(x[b, d_idx, n_start + 7], al.f32)
        if v < min7:
            min7 = v

    shared = al.make_shared((BS,), al.f32)

    # Tree-reduce each of the TILE_N output elements sequentially
    # k=0
    if n_start + 0 < N:
        shared[tid] = min0
    else:
        shared[tid] = INF
    al.syncthreads()
    if tid < 128:
        if shared[tid + 128] < shared[tid]:
            shared[tid] = shared[tid + 128]
    al.syncthreads()
    if tid < 64:
        if shared[tid + 64] < shared[tid]:
            shared[tid] = shared[tid + 64]
    al.syncthreads()
    if tid < 32:
        if shared[tid + 32] < shared[tid]:
            shared[tid] = shared[tid + 32]
    al.syncthreads()
    if tid < 16:
        if shared[tid + 16] < shared[tid]:
            shared[tid] = shared[tid + 16]
    al.syncthreads()
    if tid < 8:
        if shared[tid + 8] < shared[tid]:
            shared[tid] = shared[tid + 8]
    al.syncthreads()
    if tid < 4:
        if shared[tid + 4] < shared[tid]:
            shared[tid] = shared[tid + 4]
    al.syncthreads()
    if tid < 2:
        if shared[tid + 2] < shared[tid]:
            shared[tid] = shared[tid + 2]
    al.syncthreads()
    if tid == 0:
        if shared[1] < shared[0]:
            shared[0] = shared[1]
        if n_start + 0 < N:
            out[d_idx, n_start + 0] = al.convert(shared[0], al.bf16)
    al.syncthreads()

    # k=1
    if n_start + 1 < N:
        shared[tid] = min1
    else:
        shared[tid] = INF
    al.syncthreads()
    if tid < 128:
        if shared[tid + 128] < shared[tid]:
            shared[tid] = shared[tid + 128]
    al.syncthreads()
    if tid < 64:
