    if tid < 8:
        if shared[tid + 8] < shared[tid]:
            shared[tid] = shared[tid + 8]
    al.syncthreads()
    if tid < 4:
        if shared[tid + 4] < shared[tid]:
            shared[tid] = shared[tid + 4]
    al.syncthreads()
    if tid < 2:
        if shared[tid + 2] < shared[tid]:
            shared[tid] = shared[tid + 2]
    al.syncthreads()
    if tid == 0:
        if shared[1] < shared[0]:
            shared[0] = shared[1]
        if n_start + 1 < N:
            out[d_idx, n_start + 1] = al.convert(shared[0], al.bf16)
    al.syncthreads()

    # k=2
    if n_start + 2 < N:
        shared[tid] = min2
    else:
        shared[tid] = INF
    al.syncthreads()
    if tid < 128:
        if shared[tid + 128] < shared[tid]:
            shared[tid] = shared[tid + 128]
    al.syncthreads()
    if tid < 64:
